/**
 * Parity and engagement coverage for the packed f-tree's long-keyed EXISTS/NOT-EXISTS witnesses
 * ({@link LmdbNativePackedFtree.WitnessPlan}): every witness-shaped query must return the same result with the packed
 * engine on and off (the {@code rdf4j.lmdb.packedFtree.enabled} switch is read per evaluation, so the same store serves
 * both arms), a packed aggregate can be selected explicitly for a witness query, and no native semijoin probe may
 * remain held after a result closes. The packed-off reference uses ordinary adaptive dispatch; packed-on evaluations
 * use the supported per-query strategy selector so this test does not depend on packed f-trees outranking newer native
 * tiers.
 */
@ResourceLock(Resources.SYSTEM_PROPERTIES)
public class LmdbNativePackedFtreeWitnessTest {

	private static final String EX = "http://example.com/";
	private static final String PACKED_PROPERTY = "rdf4j.lmdb.packedFtree.enabled";
	private static final String JANINO_PROPERTY = "rdf4j.lmdb.janinoCodegen.enabled";
	private static final String PACKED_STRATEGY = LmdbNativeAttemptMetrics.PATH_PACKED_FTREE_AGGREGATE;
	private static final int PATIENTS = 64;

	private static String previousJanino;
	private String previousPacked;

	@TempDir
	File dataDir;

	private SailRepository repository;

	@BeforeAll
	static void pinJaninoOff() {
		// janino steals pinned strategies after enough queries per JVM; keep engagement deterministic
		previousJanino = System.setProperty(JANINO_PROPERTY, "false");
	}

	@AfterAll
	static void restoreJanino() {
		if (previousJanino == null) {
			System.clearProperty(JANINO_PROPERTY);
		} else {
			System.setProperty(JANINO_PROPERTY, previousJanino);
		}
	}

	@BeforeEach
	public void setUp() {
		previousPacked = System.getProperty(PACKED_PROPERTY);
		repository = new SailRepository(new LmdbStore(dataDir, new LmdbStoreConfig("spoc,posc,ospc")));
		try (SailRepositoryConnection conn = repository.getConnection()) {
			ValueFactory vf = conn.getValueFactory();
			IRI patientType = vf.createIRI(EX, "Patient");
			IRI hasEncounter = vf.createIRI(EX, "hasEncounter");
			IRI hasObservation = vf.createIRI(EX, "hasObservation");
			IRI hasCondition = vf.createIRI(EX, "hasCondition");
			IRI value = vf.createIRI(EX, "value");
			IRI flaggedCondition = vf.createIRI(EX, "cond_flagged");
			// single transaction: direct adjacency stays available for the witness probes
			conn.begin();
			for (int i = 0; i < PATIENTS; i++) {
				IRI patient = vf.createIRI(EX, "patient" + i);
				conn.add(patient, RDF.TYPE, patientType);
				for (int e = 0; e < 3; e++) {
					IRI encounter = vf.createIRI(EX, "enc" + i + "_" + e);
					conn.add(patient, hasEncounter, encounter);
					IRI observation = vf.createIRI(EX, "obs" + i + "_" + e);
					conn.add(encounter, hasObservation, observation);
					conn.add(observation, value, vf.createLiteral(50 + (i + e) % 30));
					if ((i * 7 + e) % 3 == 0) {
						conn.add(encounter, hasCondition, vf.createIRI(EX, "cond" + i + "_" + e));
					}
					if ((i * 5 + e) % 4 == 0) {
						conn.add(encounter, hasCondition, flaggedCondition);
					}
				}
			}
			conn.commit();
		}
	}

	@AfterEach
	public void tearDown() {
		if (previousPacked == null) {
			System.clearProperty(PACKED_PROPERTY);
		} else {
			System.setProperty(PACKED_PROPERTY, previousPacked);
		}
		if (repository != null) {
			repository.shutDown();
		}
	}

	private static final String PREFIX = "SELECT (COUNT(DISTINCT ?patient) AS ?c) WHERE {"
			+ " ?patient a <" + EX + "Patient> ."
			+ " ?patient <" + EX + "hasEncounter> ?enc ."
			+ " ?enc <" + EX + "hasObservation> ?obs ."
			+ " ?obs <" + EX + "value> ?value ."
			+ " FILTER(?value IN (50, 60, 70))";

	@Test
	public void existsWitnessMatchesPackedOff() {
		assertParity(PREFIX + " FILTER EXISTS { ?enc <" + EX + "hasCondition> ?cond } }");
	}

	@Test
	public void notExistsWitnessMatchesPackedOff() {
		assertParity(PREFIX + " FILTER NOT EXISTS { ?enc <" + EX + "hasCondition> ?cond } }");
	}

	@Test
	public void constantObjectWitnessMatchesPackedOff() {
		assertParity(PREFIX + " FILTER EXISTS { ?enc <" + EX + "hasCondition> <" + EX + "cond_flagged> } }");
	}

	@Test
	public void groupedWitnessMatchesPackedOff() {
		assertParity("SELECT ?patient (COUNT(DISTINCT ?enc) AS ?c) WHERE {"
				+ " ?patient a <" + EX + "Patient> ."
				+ " ?patient <" + EX + "hasEncounter> ?enc ."
				+ " FILTER NOT EXISTS { ?enc <" + EX + "hasCondition> ?cond } }"
				+ " GROUP BY ?patient");
	}

	@Test
	public void packedAggregateCanBeForcedForWitnessQuery() {
		String query = PREFIX + " FILTER NOT EXISTS { ?enc <" + EX + "hasCondition> ?cond } }";
		try (SailRepositoryConnection conn = repository.getConnection()) {
			Map<String, Long> reference = resultMap(conn, query, "false", null);
			System.setProperty(PACKED_PROPERTY, "true");
			SailTupleQuery packedQuery = prepare(conn, query, PACKED_STRATEGY);
			String plan = String.valueOf(packedQuery.explain(Explanation.Level.Executed));
			assertThat(plan).contains("nativeExecutionPath=" + PACKED_STRATEGY);
			assertThat(AdjacencyIntersectionProbe.ACTIVE_PROBES.get()).isZero();
			assertThat(resultMap(conn, query, "true", PACKED_STRATEGY)).isEqualTo(reference);
			assertThat(AdjacencyIntersectionProbe.ACTIVE_PROBES.get()).isZero();
		}
	}

	private void assertParity(String query) {
		try (SailRepositoryConnection conn = repository.getConnection()) {
			// Keep the reference on ordinary adaptive dispatch; explicitly select packed for every packed-on
			// evaluation.
			Map<String, Long> reference = resultMap(conn, query, "false", null);
			for (int round = 0; round < 6; round++) {
				assertThat(resultMap(conn, query, "true", PACKED_STRATEGY))
						.as("packed-on result (round %d)", round)
						.isEqualTo(reference);
				assertThat(AdjacencyIntersectionProbe.ACTIVE_PROBES.get())
						.as("native semijoin probes still held after result close (round %d)", round)
						.isZero();
			}
		}
	}

	private static SailTupleQuery prepare(SailRepositoryConnection conn, String query, String forcedStrategy) {
		SailTupleQuery preparedQuery = (SailTupleQuery) conn.prepareTupleQuery(QueryLanguage.SPARQL, query);
		preparedQuery.setForcedLmdbExecutionStrategy(forcedStrategy);
		return preparedQuery;
	}

	private static Map<String, Long> resultMap(SailRepositoryConnection conn, String query, String packedEnabled,
			String forcedStrategy) {
		System.setProperty(PACKED_PROPERTY, packedEnabled);
		List<BindingSet> rows = QueryResults.asList(prepare(conn, query, forcedStrategy).evaluate());
		Map<String, Long> byKey = new TreeMap<>();
		for (BindingSet row : rows) {
			String key = row.hasBinding("patient") ? row.getValue("patient").stringValue() : "";
			byKey.put(key, ((Literal) row.getValue("c")).longValue());
		}
		return byKey;
	}
}
